input.sparql:
SELECT ?zoneName ?tsid ?pointUri WHERE {
  ?zone a brick:Zone ; rdfs:label ?zoneName .
  ?point brick:hasLocation ?zone ; a brick:AirTemperatureSensor .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
}

SELECT ?zone ?zoneName ?sensor ?tsref WHERE {
  ?zone a brick:HVAC_Zone .
  ?zone rdfs:label ?zoneName .
  ?zone brick:hasPoint ?sensor .
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?tsref . }
}
